function renderDepotControls(){const host=document.querySelector('#depotControls');if(!host)return;host.replaceChildren();const status=document.createElement('p');status.id='depotAssetStatus';status.className='sub';status.textContent='Loading independent scene assets…';host.append(status);const row=document.createElement('div');row.className='directorGrid';row.innerHTML='<label>Scene time (s)<input id="depotTime" type="number" min="0" step=".1" value="'+Math.max(0,t*settings.duration-phaseTimes().depot).toFixed(1)+'"></label><button class="pill" id="depotSeek">Go to time</button>';host.append(row);row.querySelector('#depotTime').oninput=e=>seekDepot(+e.target.value);row.querySelector('#depotSeek').onclick=()=>seekDepot(+row.querySelector('#depotTime').value);const jump=document.createElement('div');jump.className='contextActions';for(const [label,age]of [['Descent',2.5],['Cargo depth pullback',8],['Shoulder',13],['Faces',25],['Two figures',29],['Full reveal',31],['Picture frame',38],['Cracks',45],['Storm & tilt',54]])toolButton(jump,label,()=>seekDepot(age));host.append(jump);const select=document.createElement('select');select.id='depotObjectSelect';select.setAttribute('aria-label','Depot object');for(const [i,o]of fx.depotObjects.entries()){const op=document.createElement('option');op.value=i;op.textContent=o.name;select.append(op)}select.value=depotObjectIndex;select.onchange=()=>{depotObjectIndex=+select.value;renderDepotControls()};host.append(select);const o=fx.depotObjects[depotObjectIndex];if(o){const fields=document.createElement('div');fields.className='contextFields';host.append(fields);depotObjectFields(fields,o);const marks=document.createElement('details');marks.innerHTML='<summary>Armband / cargo insignia</summary>';host.append(marks);if(o.type==='crate')depotMarkFields(marks,o);else marks.textContent='Uniform is part of the source image. Replace source to change it.';keyframeTools(host,o,['x','y','width','height','rotation','opacity'],()=>Math.max(0,t*settings.duration-phaseTimes().depot));toolButton(host,'Replace source…',()=>chooseAsset(o.slot));toolButton(host,o.visible===false?'Show object':'Hide object',()=>{o.visible=o.visible===false;saveEffects();renderDepotControls()})}toolField(host,'Left cloud color',fx,'depotCloudLeft','color');toolField(host,'Right cloud color',fx,'depotCloudRight','color');toolButton(host,'Reload bundled depot assets',reloadDepotAssets);updateDepotAssetStatus();toolButton(host,'Room background…',()=>chooseAsset('depotRoom'));toolButton(host,'Haze · color, thickness & drawn path…',()=>openFlowEditor(fx.depotHaze,saveEffects,'Warm depot haze'))}
const selectBeforeDepot=selectEffect;selectEffect=function(key,jump=true){selectBeforeDepot(key,jump);if(key==='depot'){const swap=controls.querySelector('#swapEffect');swap.previousElementSibling.style.display='none';swap.style.display='none';const host=document.createElement('section');host.id='depotControls';controls.querySelector('#watchEffect').after(host);renderDepotControls()}};stages.querySelectorAll('button').forEach(b=>b.onclick=()=>selectEffect(b.dataset.stage));
const frameBeforeDepot=frame;frame=function(el,p){frameBeforeDepot(el,p);if(el===base&&p*settings.duration>=phaseTimes().depot&&p*settings.duration<phaseTimes().images)stages.querySelectorAll('button').forEach(b=>b.classList.toggle('playing',b.dataset.stage==='depot'))};
const contextBeforeDepot=renderAssetContext;renderAssetContext=function(){contextBeforeDepot();const a=selectedSceneAsset;if(!a||!a.kind.startsWith('depot'))return;const host=selectionTools.querySelector('.contextFields');if(['depotFrame','depotStorm','depotLightning','depotFlag'].includes(a.kind)){const specs=a.kind==='depotFrame'?[['depotFrameStart','Reveal starts',0,60,.5],['depotFrameTime','Pullback duration',1,40,.5],['depotFrameEndScale','Final size',.1,1,.01],['depotFrameRotation','Rotation',-90,90,1],['depotFrameTilt','Perspective tilt',-75,75,1],['depotTiltStart','Tilt starts',0,65,.5],['depotTiltTime','Tilt duration',1,30,.5],['depotCrackStart','Cracks start',0,65,.5],['depotCrackTime','Crack duration',1,30,.5],['depotCrackStrength','Crack visibility',.5,5,.1],['depotFrameDarkness','Darkening on shrink',0,1,.02],['depotGlassReflection','Glass reflection',0,1,.05],['depotGlassRefraction','Glass refraction',0,5,.25]]:a.kind==='depotStorm'?[['depotStormDensity','Density',0,150,1],['depotStormSpeed','Speed',0,50,1],['depotCloudY','Position Y',0,540,1]]:a.kind==='depotFlag'?[['depotFlagX','Flag X',-100,960,1],['depotFlagY','Flag Y',0,540,1],['depotFlagScale','Flag size',.1,3,.05]]:[['depotDividerX','Divider X',0,960,1],['depotDividerWidth','Width',1,15,.5],['depotLightningBrightness','Brightness',0,3,.1],['depotLightningRate','Frequency',.1,3,.1]];toolNumbers(host,fx,specs);if(a.kind==='depotStorm'){toolField(host,'Left color',fx,'depotCloudLeft','color');toolField(host,'Right color',fx,'depotCloudRight','color')}return}if(a.kind==='depotRoom'){toolNumbers(host,fx,[['depotBrightness','Brightness',.3,1.6,.05],['depotSaturation','Color saturation',0,1.5,.05],['depotBlurStart','Initial defocus',0,30,.5],['depotBlurEnd','Final defocus',0,15,.5],['depotCameraStart','Camera starts',0,20,.5],['depotCameraEnd','Camera settles',15,45,.5],['depotCameraDistance','Initial proximity',900,1500,10],['depotCameraStartY','Initial camera height',0,350,1],['depotCameraLowY','Descent low point',250,400,1]]);toolButton(selectionTools,'Draw haze direction…',()=>openFlowEditor(fx.depotHaze,assetSave,'Depot haze'));mediaTools(selectionTools,a);return}const o=fx.depotObjects.find(o=>o.id===a.objectId);if(!o)return;if(a.kind==='depotObject'){depotObjectFields(host,o);keyframeTools(selectionTools,o,['x','y','width','height','rotation','opacity'],()=>Math.max(0,t*settings.duration-phaseTimes().depot));mediaTools(selectionTools,a)}if(o.type==='crate')depotMarkFields(host,o)};
registerCapability('template:depot',{label:'Smoke descent & supply-depot pullback',category:'Template actions',panel:'depot',render(ctx,age){renderDepot(ctx,age)}});registerCapability('depotPeople',{label:'Two depot figures & editable armbands',category:'Historical collage',defaults:{depotObjects:structuredClone(depotDefaults.depotObjects.filter(o=>o.type==='person').map(o=>({...o,start:0,fade:1}))),depotStartScale:1,depotEndScale:1},render(ctx,age,l){if(!depotEngine)return;const f={...fx,...l.params,depotObjects:l.params.depotObjects};depotEngine.paint(ctx,age,f,sprites,{transparent:true})},edit(host,l){toolButton(host,'Edit figure and insignia layers…',()=>openLayerTools(l,'depot'))}});
registerCapability('depotCargo',{label:'Canvas-covered military cargo',category:'Historical collage',defaults:{depotObjects:structuredClone(depotDefaults.depotObjects.filter(o=>o.type==='crate').map(o=>({...o,start:0,fade:1})))},render(ctx,age,l){depotEngine?.paint(ctx,age,{...fx,...l.params},sprites,{transparent:true})},edit(host,l){toolButton(host,'Edit cargo and markings…',()=>openLayerTools(l,'depot'))}});
const depotCSS=document.createElement('style');depotCSS.textContent='#depotControls input[type=number]{width:100%;background:#22252b;color:#eee;border:1px solid #444;padding:8px;border-radius:4px}#depotControls label{font-size:11px;margin:10px 0}#depotControls>select{margin:15px 0}#depotControls>button{margin:8px 5px 0 0}';document.head.append(depotCSS);syncDuration();
